import itertools
import random

def is_connected(cells):
    if not cells: return True
    start_cell = cells[0]
    visited = {start_cell}
    stack = [start_cell]
    while stack:
        curr = stack.pop()
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            neighbor = (curr[0] + dx, curr[1] + dy)
            if neighbor in cells and neighbor not in visited:
                visited.add(neighbor)
                stack.append(neighbor)
    return len(visited) == len(cells)

def get_polyominoes(area, grid_size):
    polyominoes = []
    for combo in itertools.combinations(range(grid_size * grid_size), area):
        cells = [(c // grid_size, c % grid_size) for c in combo]
        if is_connected(cells):
            polyominoes.append(cells)
    return polyominoes

def check_coloring(grid, n, polyominoes):
    for poly in polyominoes:
        colors = set()
        for r, c in poly:
            colors.add(grid[r][c])
        if len(colors) < n:
            return False, poly
    return True, None

