import itertools

def check_all_polyominoes(n, area, grid_func, grid_size):
    grid = [[grid_func(x, y) % n for y in range(grid_size)] for x in range(grid_size)]

    # Get all polyominoes of given area in the grid_size x grid_size grid
    def get_polyominoes(area, grid_size):
        polyominoes = []
        for combo in itertools.combinations(range(grid_size * grid_size), area):
            cells = [(c // grid_size, c % grid_size) for c in combo]
            if is_connected(cells):
                polyominoes.append(cells)
        return polyominoes

    polyominoes = get_polyominoes(area, grid_size)
    for poly in polyominoes:
        colors = set()
        for r, c in poly:
            colors.add(grid[r][c])
        if len(colors) < n:
            return False, poly
    return True, None

